-- READ ONLY authoritative DDL/DCL reconciliation. Compare with bound artifacts, not transport outcome.
select count(*) as history_count from supabase_migrations.schema_migrations;
select version,name,statements from supabase_migrations.schema_migrations where name in ('url_review_bound_open_v2','url_review_bound_close_v2') order by version;
select p.oid::regprocedure::text signature,p.prosecdef,p.proconfig,p.proowner,p.proacl::text,encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') prosrc_sha256,case when p.proname='review_url_result_impl' then '62efecdc19e7f39a6eeb4fba964ba0950b9b04292b0f3d6d68479d75dedd89d0' end expected_bound_prosrc_sha256 from pg_proc p where p.oid in (to_regprocedure('public.review_url_result(uuid,uuid,uuid,text,text,text,jsonb)'),to_regprocedure('private.review_url_result_impl(uuid,uuid,uuid,text,text,text,jsonb)'));
select acl_role.name as role,f.signature,has_function_privilege(acl_role.name,to_regprocedure(f.signature),'execute') as effective_execute from (values('anon'),('authenticated'),('service_role')) acl_role(name) cross join (values('public.save_url_result_draft(uuid,uuid,uuid,integer,jsonb)'),('private.save_url_result_draft_impl(uuid,uuid,uuid,integer,jsonb)'),('public.review_url_result(uuid,uuid,uuid,text,text,text,jsonb)'),('private.review_url_result_impl(uuid,uuid,uuid,text,text,text,jsonb)')) f(signature);
select p.oid::regprocedure::text signature,a.* from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.oid in (to_regprocedure('public.save_url_result_draft(uuid,uuid,uuid,integer,jsonb)'),to_regprocedure('private.save_url_result_draft_impl(uuid,uuid,uuid,integer,jsonb)'),to_regprocedure('public.review_url_result(uuid,uuid,uuid,text,text,text,jsonb)'),to_regprocedure('private.review_url_result_impl(uuid,uuid,uuid,text,text,text,jsonb)'));
select column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema='public' and table_name='content_reviews' and column_name like 'url_review_%' order by column_name;
select conname,pg_get_constraintdef(oid) definition from pg_constraint where conrelid='public.content_reviews'::regclass order by conname;
